-- --------------------------------------------------------
-- Table structure & data for table `personal_access_tokens`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `personal_access_tokens`;
CREATE TABLE `personal_access_tokens` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `tokenable_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tokenable_id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `abilities` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `personal_access_tokens_token_unique` (`token`),
  KEY `personal_access_tokens_tokenable_type_tokenable_id_index` (`tokenable_type`,`tokenable_id`),
  KEY `personal_access_tokens_expires_at_index` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- Table structure & data for table `pages`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `pages`;
CREATE TABLE `pages` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `meta_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('draft','published') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'published',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pages_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `pages` (`id`, `title`, `slug`, `meta_title`, `meta_description`, `content`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Home Page', 'home', 'FS Real Estate Advisory - Premium Dubai Properties', 'Discover luxury properties and real estate opportunities in Dubai.', '{"hero":{"heading":"DISCOVER THE RIGHT PROPERTY of the OPPORTUNITY.","mainHeading":"DISCOVER THE RIGHT PROPERTY of the OPPORTUNITY.","title":"DISCOVER THE RIGHT PROPERTY of the OPPORTUNITY.","tagline":"Curated opportunities. Intelligent insights. Aligned with your goals. tio start a better life","badge":"Curated opportunities. Intelligent insights. Aligned with your goals. tio start a better life","titleLine1":"DISCOVER THE","titleLine2":"RIGHT PROPERTY of the","titleLine3":"OPPORTUNITY.","subheading":"Curated opportunities. Intelligent insights. Aligned with your goals. tio start a better life","primaryCtaText":"Start AI Assessment rn","primaryCtaLink":"\\/ai-assessment","secondaryCtaText":"Browse Opportunities rn","secondaryCtaLink":"\\/the-valley","backgroundImage":"\\/buy_hero.png","coverImage":"\\/buy_hero.png","bgImage":"\\/buy_hero.png","detailHtml":"<h2>DISCOVER THE <span style=\\"color:#BFA16A\\">RIGHT PROPERTY<\\/span> OPPORTUNITY.<\\/h2><p>Curated opportunities. Intelligent insights. Aligned with your goals.<\\/p>"},"featureBar":[{"id":"ai-advisory","title":"AI Advisory Engine","description":"Personalized recommendations based on your goals.","icon":"\\/ai.png"},{"id":"fs-scores","title":"FS Advisory Scores","description":"Proprietary rating across 10+ key factors.","icon":"\\/fs score.png"},{"id":"curated-oppo","title":"Curated Opportunities","description":"Only opportunities that meet our advisory standards.","icon":"\\/curated oppo.png"},{"id":"expert-guidance","title":"Expert Guidance","description":"Human expertise at every step of your journey.","icon":"\\/exp guidance.png"}],"metaKeywords":null,"ogImage":"\\/buy_hero.png","featureBarDetail":"<h3>Advisory &amp; Feature Bar<\\/h3><p>Proprietary algorithms and seasoned real estate advisors deliver tailored opportunities.<\\/p>","featureBarBgImage":"\\/dubai hills.png","opportunities":{"title":"Opportunities We Currently Recommend to you","heading":"Opportunities We Currently Recommend to you","titleLine1":"Opportunities We","titleLine2":"Currently Recommend to you","tagline":"FEATURED INVESTMENTS","badge":"FEATURED INVESTMENTS","description":"Hand-picked, high-yield developments across prime UAE communities.","contentText":"Hand-picked, high-yield developments across prime UAE communities.","viewAllLink":"\\/project-main-page","cards":[{"id":"2","title":"Grand Polo Club & Resort","developer":"By Emaar","score":89,"tag":"LUXURY LIVING","bestFor":"Luxury Lifestyle","price":"AED 4.2M","image":"\\/grandpolo_club.png"},{"id":"3","title":"Dubai Hills Estate","developer":"By Emaar","score":87,"tag":"FAMILY LIVING","bestFor":"End Users & Investors","price":"AED 1.8M","image":"\\/dubai hills.png"},{"id":"1792960537576","title":"the valley","developer":"By Emaar","score":90,"tag":"growing family","bestFor":"Investors & Families","price":"AED 1.6M","image":"\\/thevalley.png"}]},"community":{"heading":"Explore by Community","tagline":"FEATURED DISTRICTS","badge":"FEATURED DISTRICTS","description":"Discover master-planned developments and luxury waterfront neighborhoods.","contentText":"Discover master-planned developments and luxury waterfront neighborhoods.","items":[{"name":"Dubai Creek Harbour","icon":"\\/creekicon.png","href":"\\/communities\\/dubai-creek-harbour"},{"name":"Palm Jumeirah","icon":"\\/palmjumeriah icon.png","href":"\\/communities\\/palm-jumeirah"},{"name":"Business Bay","icon":"\\/creekicon.png","href":"\\/communities\\/business-bay"},{"name":"Dubai Hills Estate","icon":"\\/dubai_hills.png","href":"\\/communities\\/dubai-hills-estate"},{"name":"Downtown Dubai","icon":"\\/dubai_hills.png","href":"\\/communities\\/downtown-dubai"}]},"reviews":{"heading":"What Our Clients Say","tagline":"FROM CLIENT TESTIMONIALS","introText":"Verified experiences from global investors and residents who achieved their real estate goals with FS Advisory.","items":[{"id":"1","name":"Omer Khan","role":"Verified Client","content":"I was looking at the real estate market of Dubai and got in contact with Ms. Hana Taghdis of FS Advisory. She showed me multiple projects and finally I was able to select a unit of my choice.","rating":1},{"id":"2","name":"Nathalie Syvak","role":"Verified Client","content":"Our real estate agent is Yulia Kravchenko, we are very pleased with her work and I would like to note her approach to the client.","rating":3},{"id":"3","name":"Mike Mike","role":"Verified Client","content":"Ultimate admiration! I wanted to know more about the real estate business in Dubai. God sent me a unique intelligent young lady Yulia Kravchenko.","rating":3}],"detailHtml":"<h2>What Our <span style=\\"color:#BFA16A\\">Clients Say<\\/span><\\/h2><p>Verified experiences from global investors and residents.<\\/p>","backgroundImage":"\\/thevalley.png"},"faqs":{"heading":"Frequently Asked Questions","tagline":"UAE off-plan property \\u00b7 Buyer guide","mainHeading":"Everything you need to know about UAE off-plan property","contentText":"Answers To The Questions We Hear Most From People Exploring An Off-Plan Purchase In The UAE \\u2014 From How The Process Works To Ownership, Payment Plans, And What To Check Before You Commit.","items":[{"id":"faq-1","question":"What Does \\"Off-Plan\\" Actually Mean?","answer":"Off-plan property is real estate purchased before it is fully constructed. Buyers invest directly from developers at launch pricing with structured milestone-based installment plans."},{"id":"faq-2","question":"How Do Off-Plan Payment Plans Typically Work?","answer":"Payment plans are structured schedules spread across the construction timeline, typically 10-20% down payment and installments tied to construction milestones."},{"id":"faq-3","question":"Can An Off-Plan Purchase Qualify Me For A UAE Residency Visa?","answer":"Yes, investing in UAE property valued at AED 750,000+ can qualify you for an investor visa, while AED 2M+ qualifies for the 10-year UAE Golden Visa."},{"id":"faq-4","question":"How Are Off-Plan Buyer Payments Protected?","answer":"In Dubai, all buyer funds are deposited into government-regulated RERA escrow accounts released only against verified construction progress."}],"detailHtml":"<h2>Buyer Guide &amp; <span style=\\"color:#BFA16A\\">Frequently Asked Questions<\\/span><\\/h2><p>Clear, direct answers for navigating off-plan property investment in Dubai.<\\/p>","backgroundImage":"\\/buy_hero.png"},"assessment":{"heading":"What is your primary goal?","tagline":"AI ENGINE ASSESSMENT","subheading":"This helps us tailor recommendations to what matters most to you.","detailHtml":"<h2>What is your <span style=\\"color:#BFA16A\\">primary goal?<\\/span><\\/h2><p>This helps us tailor recommendations to what matters most to you.<\\/p>","backgroundImage":"\\/ai_engine_hero.jpg","goals":[{"id":"family-home","title":"Family Home","subtitle":"Find The Perfect Place To Put Down Roots"},{"id":"investment","title":"Investment","subtitle":"Build Wealth Through Real Estate"},{"id":"global-clients","title":"Global Clients","subtitle":"Cross-Border Advisory With Local Expertise You Can Trust."},{"id":"passive-income","title":"Passive Income","subtitle":"Finding The Right Home In The Right Community."},{"id":"capital-growth","title":"Capital Growth","subtitle":"Building Wealth Through Strategic Real Estate Investments."},{"id":"luxury-lifestyle","title":"Luxury Lifestyle","subtitle":"Cross-Border Advisory With Local Expertise You Can Trust."}]},"customSections":[],"longContent":{"detailHtml":"<h2><span data-metadata=\\"&lt;!--(figmeta)eyJmaWxlS2V5IjoiazJUa1U4cGRuamZDMG43SGtNcEJiSyIsInBhc3RlSUQiOjI2NTE4NzM2NSwiZGF0YVR5cGUiOiJzY2VuZSIsImVkaXRvclR5cGUiOiJkZXNpZ24iLCJlbnZpcm9ubWVudCI6Ind3dy5maWdtYS5jb20iLCJzZWxlY3RlZE5vZGVEYXRhIjoiNzYyOjg0NTF8MzF8MHwwIiwiaW1hZ2VIYXNoZXMiOnt9fQo=(\\/figmeta)--&gt;\\"><\\/span><span data-buffer=\\"&lt;!--(figma)ZmlnLWtpd2l